CREATE OR REPLACE FUNCTION public.parent_module_access(_uid uuid,_parent text,_id uuid,_module text,_level text DEFAULT 'view') RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE co uuid; BEGIN IF _parent NOT IN ('hms_handbook_versions','hms_submissions','hms_templates','calculations','customers','customer_contacts','planning_projects') THEN RETURN false; END IF; IF _parent='customer_contacts' THEN SELECT c.company_id INTO co FROM public.customer_contacts cc JOIN public.customers c ON c.id=cc.customer_id WHERE cc.id=_id; ELSE EXECUTE format('SELECT company_id FROM public.%I WHERE id=$1',_parent) INTO co USING _id; END IF; RETURN public.has_company_access(_uid,co,_module,_level); END $$;
REVOKE ALL ON FUNCTION public.parent_module_access(uuid,text,uuid,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.parent_module_access(uuid,text,uuid,text,text) TO authenticated,service_role;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT * FROM (VALUES ('hms_handbook_sections','hms_handbook_versions','version_id','hms'),('hms_submission_answers','hms_submissions','submission_id','hms'),('hms_submission_participants','hms_submissions','submission_id','hms'),('hms_submission_signatures','hms_submissions','submission_id','hms'),('hms_template_items','hms_templates','template_id','hms'),('hms_template_sections','hms_templates','template_id','hms'),('calculation_items','calculations','calculation_id','finance'),('calculation_lines','calculations','calculation_id','finance'),('customer_contacts','customers','customer_id','customers'),('customer_contact_tag_relations','customer_contacts','contact_id','customers')) v(child,parent,col,module) LOOP
 EXECUTE format('CREATE POLICY phase2_parent_view ON public.%I AS RESTRICTIVE FOR SELECT TO authenticated USING(public.parent_module_access(auth.uid(),%L,%I,%L,''view''))',r.child,r.parent,r.col,r.module);
 EXECUTE format('CREATE POLICY phase2_parent_insert ON public.%I AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.parent_module_access(auth.uid(),%L,%I,%L,''edit''))',r.child,r.parent,r.col,r.module);
 EXECUTE format('CREATE POLICY phase2_parent_update ON public.%I AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.parent_module_access(auth.uid(),%L,%I,%L,''edit'')) WITH CHECK(public.parent_module_access(auth.uid(),%L,%I,%L,''edit''))',r.child,r.parent,r.col,r.module,r.parent,r.col,r.module);
 EXECUTE format('CREATE POLICY phase2_parent_delete ON public.%I AS RESTRICTIVE FOR DELETE TO authenticated USING(public.parent_module_access(auth.uid(),%L,%I,%L,''admin''))',r.child,r.parent,r.col,r.module);
 END LOOP; END $$;
DROP POLICY phase2_people_write ON public.people;
CREATE POLICY phase2_people_insert ON public.people AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.is_super_admin(auth.uid()));
CREATE POLICY phase2_people_update ON public.people AS RESTRICTIVE FOR UPDATE TO authenticated USING(public.person_module_access(auth.uid(),id,'edit')) WITH CHECK(public.person_module_access(auth.uid(),id,'edit'));
CREATE POLICY phase2_people_delete ON public.people AS RESTRICTIVE FOR DELETE TO authenticated USING(public.person_module_access(auth.uid(),id,'admin'));
CREATE POLICY phase2_personnel_accounts ON public.user_accounts FOR SELECT TO authenticated USING(public.person_module_access(auth.uid(),person_id,'view'));
CREATE POLICY phase2_personnel_people ON public.people FOR SELECT TO authenticated USING(public.person_module_access(auth.uid(),id,'view'));
CREATE POLICY phase2_personnel_employment ON public.employment_profiles FOR SELECT TO authenticated USING(public.has_company_access(auth.uid(),company_id,'employees','view'));
CREATE POLICY phase2_customer_view ON public.customers FOR SELECT TO authenticated USING(public.has_company_access(auth.uid(),company_id,'customers','view'));
CREATE POLICY phase2_organisation_view ON public.compliance_org_roles FOR SELECT TO authenticated USING(public.has_company_access(auth.uid(),company_id,'organisation','view'));
CREATE POLICY phase2_organisation_manage ON public.compliance_org_roles FOR ALL TO authenticated USING(public.has_company_access(auth.uid(),company_id,'organisation','view')) WITH CHECK(public.has_company_access(auth.uid(),company_id,'organisation','edit'));
CREATE OR REPLACE FUNCTION public.planning_finance_access(_project_id uuid,_level text DEFAULT 'view') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.planning_projects p WHERE p.id=_project_id AND public.has_planning_project_access(p.id) AND public.has_company_access(auth.uid(),p.company_id,'finance',_level)) $$;
DO $$ DECLARE n text; d text; BEGIN FOREACH n IN ARRAY ARRAY['get_planning_finance','set_planning_project_finance','set_planning_wp_finance'] LOOP SELECT pg_get_functiondef(p.oid) INTO d FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname=n; IF n='get_planning_finance' OR n='set_planning_project_finance' THEN d:=replace(d,'public.can_view_planning_finance()',format('public.planning_finance_access(_project_id, %L)',CASE WHEN n='get_planning_finance' THEN 'view' ELSE 'edit' END)); ELSE d:=replace(d,'public.can_view_planning_finance()','public.planning_finance_access(pid, ''edit'')'); END IF; EXECUTE d; END LOOP; END $$;